import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import PropTypes from 'prop-types';

/**
 * GarageSidebar - Sidebar สำหรับอู่ซ่อม
 * เมนูหลัก: ภาพรวม, รายการซ่อม, คำขออนุมัติ, ประวัติการซ่อม
 * 
 * Props:
 * - collapsed: boolean - เมื่อเป็น true จะแสดงแค่ icon
 */
const GarageSidebar = ({ collapsed = false }) => {
  const location = useLocation();

  const menuItems = [
    {
      id: 'dashboard',
      title: 'ภาพรวม',
      icon: 'dashboard',
      path: '/garage/dashboard',
      description: 'สถิติและภาพรวมการซ่อม'
    },
    {
      id: 'repairs',
      title: 'รายการซ่อม',
      icon: 'build_circle',
      path: '/garage/repairs',
      description: 'งานซ่อมทั้งหมด',
      badge: 8, // จำนวนงานที่กำลังดำเนินการ
    },
    {
      id: 'pending',
      title: 'รอรับงาน',
      icon: 'schedule',
      path: '/garage/pending',
      description: 'คำขอใหม่จากลูกค้า',
      badge: 3,
      highlight: true, // เน้นเมนูนี้
    },
    {
      id: 'approvals',
      title: 'คำขออนุมัติ',
      icon: 'request_quote',
      path: '/garage/approvals',
      description: 'รายการเพิ่มเติมที่ขออนุมัติ',
      badge: 2,
    },
    {
      id: 'history',
      title: 'ประวัติการซ่อม',
      icon: 'history',
      path: '/garage/history',
      description: 'งานที่เสร็จสิ้นแล้ว'
    },
  ];

  // เช็คว่า path ปัจจุบันตรงกับ menu item หรือไม่
  const isActive = (path) => location.pathname.startsWith(path);

  return (
    <aside className={`
      bg-white border-r border-neutral-200 h-screen sticky top-16 overflow-y-auto custom-scrollbar animate-slide-in-left transition-all duration-300
      ${collapsed ? 'w-20' : 'w-64'}
    `}>
      <div className={`${collapsed ? 'p-3' : 'p-6'}`}>

        {/* 🔹 โหมดย่อ - แสดงแค่ Icon */}
        {collapsed ? (
          <nav className="space-y-2">
            {menuItems.map((item) => (
              <Link
                key={item.id}
                to={item.path}
                className={`
                  group relative flex items-center justify-center w-full h-14 rounded-xl transition-all duration-300
                  ${isActive(item.path)
                    ? 'bg-gradient-to-br from-orange-500 to-red-500 text-white shadow-button'
                    : 'text-neutral-600 hover:bg-neutral-50 hover:text-orange-600'
                  }
                `}
                title={item.title}
              >
                {/* Icon */}
                <span className={`
                  material-icons-round text-2xl transition-transform duration-300 group-hover:scale-110
                  ${isActive(item.path) ? 'text-white' : 'text-neutral-400'}
                `}>
                  {item.icon}
                </span>

                {/* Badge */}
                {item.badge && (
                  <span className={`
                    absolute top-2 right-2 w-5 h-5 text-xs font-bold rounded-full flex items-center justify-center
                    ${item.highlight
                      ? 'bg-error text-white animate-bounce'
                      : 'bg-orange-500 text-white'
                    }
                  `}>
                    {item.badge}
                  </span>
                )}

                {/* Tooltip */}
                <div className="absolute left-full ml-2 px-3 py-2 bg-neutral-800 text-white text-sm rounded-lg opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-300 whitespace-nowrap z-50">
                  {item.title}
                  <div className="absolute top-1/2 -left-1 -translate-y-1/2 w-2 h-2 bg-neutral-800 rotate-45"></div>
                </div>
              </Link>
            ))}
          </nav>
        ) : (
          /* 🔹 โหมดขยาย - แสดงเต็ม */
          <>
            {/* Header */}
            <div className="mb-6">
              <h2 className="text-sm font-semibold text-neutral-400 uppercase tracking-wide mb-2">
                เมนูหลัก
              </h2>
              <div className="h-1 w-12 bg-gradient-to-r from-orange-500 to-red-500 rounded-full"></div>
            </div>

            {/* Menu Items */}
            <nav className="space-y-1">
              {menuItems.map((item) => (
                <Link
                  key={item.id}
                  to={item.path}
                  className={`
                    group flex items-start gap-3 px-4 py-3 rounded-xl transition-all duration-300
                    ${isActive(item.path)
                      ? 'bg-gradient-to-br from-orange-500 to-red-500 text-white shadow-button'
                      : 'text-neutral-600 hover:bg-neutral-50 hover:text-orange-600'
                    }
                  `}
                >
                  {/* Icon */}
                  <span className={`
                    material-icons-round text-2xl transition-transform duration-300 group-hover:scale-110
                    ${isActive(item.path) ? 'text-white' : 'text-neutral-400'}
                    ${item.highlight && !isActive(item.path) ? 'text-error' : ''}
                  `}>
                    {item.icon}
                  </span>

                  {/* Content */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between mb-1">
                      <span className={`font-medium text-sm ${isActive(item.path) ? 'text-white' : ''}`}>
                        {item.title}
                      </span>

                      {/* Badge */}
                      {item.badge && (
                        <span className={`
                          px-2 py-0.5 text-xs font-bold rounded-full
                          ${isActive(item.path)
                            ? 'bg-white/20 text-white'
                            : item.highlight
                              ? 'bg-error text-white animate-bounce'
                              : 'bg-orange-500 text-white'
                          }
                        `}>
                          {item.badge}
                        </span>
                      )}
                    </div>

                    {/* Description */}
                    {item.description && (
                      <p className={`
                        text-xs line-clamp-1
                        ${isActive(item.path) ? 'text-white/80' : 'text-neutral-400'}
                      `}>
                        {item.description}
                      </p>
                    )}
                  </div>
                </Link>
              ))}
            </nav>

            {/* Quick Actions */}
            <div className="mt-8">
              <h3 className="text-sm font-semibold text-neutral-400 uppercase tracking-wide mb-3">
                การดำเนินการด่วน
              </h3>
              <div className="space-y-2">
                <Link
                  to="/garage/manual-claim"
                  className="flex items-center gap-3 p-3 bg-orange-50 text-orange-700 hover:bg-orange-100 rounded-lg transition-colors duration-200"
                >
                  <span className="material-icons-round">note_add</span>
